    content: "";
    position: absolute;
    width: 0;
    height: 0;
    top: 0;
    right: -3.2rem;
    border-top: 2.3rem solid transparent;
    border-bottom: 2.3rem solid transparent;
    border-left: 3.2rem solid #F5F6F8;
    z-index: 2;
}

