.egovuiForm-checkbox-wrapper .egovuiForm-label::before {
    display: block;
    position: absolute;
    top: 0.6rem;
    left: 0.6rem;
    transform: translate(-50%, -50%);
    width: 1rem !important;
    height: 1rem !important;
    box-sizing: border-box;
    content: "";
