/* Tree */
.egovuiForm-tree-panel {
    position: relative;
}

.egovuiForm-tree-panel::after {
    content: "";
    position: absolute;
    top: 0;
    right: 0;
    width: 1rem;
    height: 100%;
    background-color: #FFFFFF;
    z-index: -1;
}

.egovuiForm-tree-header {
    display: flex;
    align-items: center;
    height: 3.5rem;
    line-height: 2.4rem;
    border-bottom: 0.1rem solid #D2D4DC;
}

.egovuiForm-tree-header>ul {
