}

.egovuiForm-tree li {
    position: relative;
    border: 0;
    border-color: transparent;
    border-style: solid;
}

.egovuiForm-tree li:last-child::after {
    content: "";
    position: absolute;
    display: block;
    width: 100%;
    left: 0;
    bottom: -0.2rem;
    height: 0.2rem;
    z-index: -1;
}

.egovuiForm-tree li:last-child.egovuiForm-parent:not(.egovuiForm-tree-close)::after {
