.egovuiForm-tree .drop-insert>span::before {
    content: "";
    position: absolute;
    top: -0.2rem;
    right: 0;
    z-index: -1;
    height: 2.4rem;
    width: 999rem;
    background-color: #D7D7D7;
}

.egovuiForm-tree .drop-before::after {
    content: "";
    position: absolute;
    top: -0.2rem;
    right: 0;
    left: auto !important;
    z-index: -1;
    height: 0.2rem;
    width: 999rem !important;
    background-color: #333333;
}

.egovuiForm-tree .drop-after::after {
    content: "";
    position: absolute;
    bottom: -0.2rem;
    right: 0;
    left: auto !important;
    z-index: -1;
    height: 0.2rem;
    width: 999rem !important;
    background-color: #333333;
}

