.egovuiForm-dialog {
    position: fixed;
    top: 50%;
    bottom: 50%;
    min-width: 34rem;
    max-height: 64rem;
    border: 0;
    padding: 3rem 4rem;
    background-color: #FFFFFF;
    color: #333333;
}

.egovuiForm-dialog::-webkit-backdrop {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    background: rgba(0, 0, 0, 0.6);
}

.egovuiForm-dialog::backdrop {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    background: rgba(0, 0, 0, 0.6);
}

.egovuiForm-dialog+.backdrop {
