/* nav menu */
.egovuiForm-nav-menu {
    position: absolute;
    top: 0;
    left: 0;
    bottom: 0;
    min-height: 40rem;
    z-index: 200;
}

.egovuiForm-nav-menu .egovuiForm-nav-menu-inner {
    display: none;
    position: relative;
    z-index: 1;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    height: 100%;
}

.egovuiForm-nav-menu .egovuiForm-nav-menu-inner #menu {
